// ---------------------------------------------------------------- rich rendering: Markdown (marked) -> sanitised HTML (DOMPurify), code (highlight.js), math (KaTeX)
// All four libraries are vendored (Web/vendor/*) and run offline. Model output is untrusted: it is HTML-escaped where marked would pass raw HTML
// through, the result goes through DOMPurify, and KaTeX / highlight.js output (generated by the libraries from escaped input) is added afterwards.
const MATH_OPEN = '', MATH_CLOSE = '';

// math is cut out before Markdown sees it (so _ and * inside formulas survive) and put back after sanitising; code is left alone
function extractMath(text) {
  const items = [];
  const hold = (tex, display) => MATH_OPEN + (items.push({tex, display}) - 1) + MATH_CLOSE;
  const parts = text.split(/(```[\s\S]*?(?:```|$)|`[^`\n]*`)/);
  for (let i = 0; i < parts.length; i += 2) {                       // even parts are outside code
    parts[i] = parts[i]
      .replace(/\$\$([\s\S]+?)\$\$/g, (_, t) => hold(t, true))
      .replace(/\\\[([\s\S]+?)\\\]/g, (_, t) => hold(t, true))
      .replace(/\\\(([\s\S]+?)\\\)/g, (_, t) => hold(t, false))
      .replace(/(?<![\\$\d])\$(?!\s)([^$\n]+?)(?<!\s)\$(?![\d$])/g, (_, t) => hold(t, false));
  }
  return {text: parts.join(''), items};
}
function putMath(html, items) {
  return html.replace(/(\d+)/g, (_, n) => {
    const it = items[+n]; if (!it) return '';
    try { return katex.renderToString(it.tex.trim(), {displayMode: it.display, throwOnError: false, strict: 'ignore', trust: false, output: 'htmlAndMathml'}); }
    catch (e) { return `<code>${esc(it.tex)}</code>`; }
  });
}

const escapeHtml = s => String(s).replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));
const SAFE_HREF = /^(https?:|mailto:|#)/i;
let markedReady = false;
function setupMarked() {
  if (markedReady || typeof marked === 'undefined') return;
  markedReady = true;
  marked.use({
    gfm: true, breaks: true,
    renderer: {
      code(code, info) {
        const lang = (info || '').trim().split(/\s+/)[0].toLowerCase();
        let body;
        if (lang && hljs.getLanguage(lang)) { try { body = hljs.highlight(code, {language: lang, ignoreIllegals: true}).value; } catch (e) { body = escapeHtml(code); } }
        else body = escapeHtml(code);
        return `<div class="code"><div class="code-head"><span>${escapeHtml(lang || 'text')}</span><button type="button" class="copy">Copy</button></div><pre><code class="hljs">${body}</code></pre></div>`;
      },
      html(h) { return escapeHtml(typeof h === 'string' ? h : h.text); },                    // raw HTML in a model answer is shown as text
      link(href, title, text) {
        if (typeof href === 'object') ({href, title, text} = href);
        if (!SAFE_HREF.test(href || '')) return text;
        return `<a href="${escapeHtml(href)}"${title ? ` title="${escapeHtml(title)}"` : ''} target="_blank" rel="noopener noreferrer">${text}</a>`;
      },
      image(href, title, text) {                                                              // no remote image loads from model output
        if (typeof href === 'object') ({href, title, text} = href);
        if (/^data:image\/(png|jpe?g|gif|webp);base64,/i.test(href || '')) return `<img src="${escapeHtml(href)}" alt="${escapeHtml(text || '')}">`;
        return SAFE_HREF.test(href || '') ? `<a href="${escapeHtml(href)}" target="_blank" rel="noopener noreferrer">[image: ${escapeHtml(text || href)}]</a>` : escapeHtml(text || '');
      },
    },
  });
  DOMPurify.addHook('afterSanitizeAttributes', node => {
    if (node.tagName === 'A') { node.setAttribute('rel', 'noopener noreferrer'); if (node.getAttribute('target')) node.setAttribute('target', '_blank'); }
  });
}
const SANITIZE = {ADD_ATTR: ['target'], FORBID_TAGS: ['style', 'form', 'iframe', 'object', 'embed', 'link', 'meta', 'base'], FORBID_ATTR: ['style']};

const MD_CACHE = new Map();
function renderMarkdown(src) {
  src = String(src ?? '');
  if (typeof marked === 'undefined' || typeof DOMPurify === 'undefined') return escapeHtml(src);       // libraries missing: still safe
  const hit = MD_CACHE.get(src); if (hit !== undefined) return hit;
  setupMarked();
  const {text, items} = extractMath(src);
  let html;
  try { html = DOMPurify.sanitize(marked.parse(text), SANITIZE); } catch (e) { html = escapeHtml(src); }
  html = typeof katex !== 'undefined' ? putMath(html, items) : html;
  if (MD_CACHE.size > 300) MD_CACHE.delete(MD_CACHE.keys().next().value);
  MD_CACHE.set(src, html);
  return html;
}

// an answer may carry <think>…</think> itself (models whose server does not split it): shown as a collapsed block, the rest as Markdown
function renderAnswer(content, thinkingNow) {
  const out = []; let rest = String(content ?? '');
  const re = /<think>([\s\S]*?)(<\/think>|$)/;
  for (let m; (m = re.exec(rest));) {
    if (m.index) out.push(renderMarkdown(rest.slice(0, m.index)));
    const closed = m[2] === '</think>';
    out.push(`<details class="think"${!closed && thinkingNow ? ' open' : ''}><summary>${closed ? 'Thought' : 'Thinking…'}</summary>${escapeHtml(m[1].trim())}</details>`);
    rest = rest.slice(m.index + m[0].length);
  }
  if (rest) out.push(renderMarkdown(rest));
  return out.join('');
}
function renderReasoning(m, isLast) {
  if (!m.reasoning) return '';
  const thinking = !!abort && isLast && !m.content;                                         // open while it thinks, folded once the answer starts
  const secs = m.stats?.thinkSeconds ?? (m.thinkMs ? m.thinkMs / 1000 : null);
  const title = thinking ? 'Thinking…' : secs ? `Thought for ${secs < 10 ? secs.toFixed(1) : Math.round(secs)} s` : 'Reasoning';
  return `<details class="think"${thinking ? ' open' : ''}><summary>${title}</summary><div class="think-body">${escapeHtml(m.reasoning)}</div></details>`;
}

// copy buttons of code blocks
document.addEventListener('click', e => {
  const b = e.target.closest?.('.code .copy'); if (!b) return;
  const code = b.closest('.code').querySelector('code').textContent;
  navigator.clipboard.writeText(code).then(() => { b.textContent = 'Copied'; setTimeout(() => { b.textContent = 'Copy'; }, 1200); }).catch(() => {});
});

// while an answer streams, re-render at most every 50 ms instead of on every token
const _renderMsgsNow = renderMsgs;
let renderTimer = null, renderPending = false;
renderMsgs = function () {
  if (!abort) { clearTimeout(renderTimer); renderTimer = null; renderPending = false; return _renderMsgsNow(); }
  if (renderTimer) { renderPending = true; return; }
  _renderMsgsNow();
  renderTimer = setTimeout(() => { renderTimer = null; if (renderPending) { renderPending = false; renderMsgs(); } }, 50);
};

// payloads that must come out harmless; run window.renderSelfTest() in the browser console (returns the list of failures)
window.renderSelfTest = () => {
  const bad = [];
  const probe = (name, src, test) => { const div = document.createElement('div'); div.innerHTML = renderMarkdown(src); if (!test(div)) bad.push(name); };
  probe('img onerror', '<img src=x onerror=alert(1)>', d => !d.querySelector('img') && !/onerror=/.test(d.innerHTML.replace(/&lt;[^>]*&gt;/g, '')));
  probe('script tag', '<script>alert(1)</script>', d => !d.querySelector('script'));
  probe('javascript link', '[x](javascript:alert(1))', d => !d.querySelector('a[href^="javascript"]'));
  probe('data link', '[x](data:text/html;base64,PHNjcmlwdD4=)', d => !d.querySelector('a[href^="data"]'));
  probe('svg onload', '<svg onload=alert(1)>', d => !d.querySelector('svg'));
  probe('remote image', '![t](https://evil.example/p.png)', d => !d.querySelector('img'));
  probe('math html', '$\\href{javascript:alert(1)}{x}$', d => !d.querySelector('a[href^="javascript"]'));
  probe('event attr in code lang', '```"><img src=x onerror=alert(1)>\ncode\n```', d => !d.querySelector('img'));
  probe('link rel', '[ok](https://example.com)', d => d.querySelector('a')?.rel.includes('noopener'));
  return bad;
};
